#!/usr/bin/env python3
"""fix_act_1_data.py -- Three-Act Evolution, part 1 of 5: DATA + art.

Adds DATA.acts (Thane of Cawdor, Tyrant of Dunsinane) and DATA.actGate
(Macbeth climax/theme gate questions) in a new <script> placed just before
the engine IIFE, and stores both portraits in assets/assets.json under the
next free asset ids.

Additive only. Refuses to run twice. Writes src/game.src.html.bak and
assets/assets.json.bak. Run from the repo root:  python3 fix_act_1_data.py
"""
import json, os, re, shutil, sys

SRC = "src/game.src.html"
ASSETS = "assets/assets.json"
MARK = "/* THREE-ACT EVOLUTION: DATA */"
ANCHOR = "\n<script>\n/* ACADEMIC BATTLE CARDS"

IMG_THANE = ""
IMG_TYRANT = ""

def die(msg):
    sys.exit("[fix_act_1_data] ABORT: " + msg)

if not os.path.exists(SRC): die(SRC + " not found -- run from the repo root")
if not os.path.exists(ASSETS): die(ASSETS + " not found -- run from the repo root")
src = open(SRC, encoding="utf-8").read()
if MARK in src: die("already applied")
if src.count("romeojuliet") < 1: die("this does not look like the live src (no romeojuliet)")
if src.count(ANCHOR) != 1: die("engine anchor found %d times (need 1)" % src.count(ANCHOR))
if "DATA.acts" in src: die("DATA.acts already exists")

assets = json.load(open(ASSETS, encoding="utf-8"))
used = {int(k[1:]) for k in assets if re.fullmatch(r"a\d+", k)}
used |= {int(n) for n in re.findall(r"__ABCASSET_(\d+)__", src)}
nxt = max(used) + 1
id_thane, id_tyrant = nxt, nxt + 1
if "a%d" % id_thane in assets or "a%d" % id_tyrant in assets: die("asset id collision")

block = r"""
<script>
MARK
(function(){ var D=window.DATA; if(!D) return;
  D.acts = [
    { id:"macbeth_thane_of_cawdor", deck:"macbeth", act:2, from:"macbeth", base:["macbeth","macbeth"], plot:"hit",
      name:"Thane of Cawdor", hp:160, archetype:"Outlaw", accent:"#5A6E8A", tags:["Thane"],
      img:"data:image/webp;base64,__ABCASSET_IDTHANE__", imgpos:"50% 10%", hpos:"50% 22%",
      atk:{n:"No Armour There", t:"\u201cNothing can stop me...\u201d Gains \ud83d\udde1\ufe0f Pierce.", cost:3, dmg:50, flags:["pierce"], label:"50/3"},
      blk:{n:"Slip the Knot", t:"Macbeth eludes punishment. Prevent the next \ud83e\ude79 Glue.", cost:2, block:30, immuneNext:["glue"], label:"30/2"} },
    { id:"macbeth_tyrant_of_dunsinane", deck:"macbeth", act:3, from:"macbeth_thane_of_cawdor", base:["macbeth","macbeth"], plot:"climaxQ", resolution:"tragic",
      name:"Tyrant of Dunsinane", hp:190, archetype:"Fallen", accent:"#5A6E8A", tags:["King"],
      img:"data:image/webp;base64,__ABCASSET_IDTYRANT__", imgpos:"50% 8%", hpos:"50% 14%",
      atk:{n:"Final Stand", t:"\u201cMy blood and my blade will cut through my enemies.\u201d Costs 20 of your own HP.", cost:3, dmg:70, sacrifice:20, label:"70/3"},
      blk:{n:"Sleep No More", t:"\u201cWhat more can I sacrifice?!\u201d Discard a random card from hand to resolve.", cost:1, block:30, selfDiscardHand:1, label:"30/1"},
      passive:{ id:"paranoia", name:"Violent Paranoia", text:"Attacks deal +20 while this card is below half health. Caveat: it can never be healed.", lowHpAtkAdd:20, noHeal:true } }
  ];
  D.actGate = D.actGate || {};
  D.actGate.macbeth = [
    { tag:"climax", q:"What finally breaks Macbeth\u2019s confidence in the last battle?", opts:["The witches take back their prophecy","Macduff reveals he was not born in the ordinary way","Lady Macbeth\u2019s ghost appears to him","Fleance returns with an army"], ans:1 },
    { tag:"climax", q:"How does Birnam Wood \u201ccome to Dunsinane\u201d?", opts:["A storm uproots the forest","The witches enchant the trees","Malcolm\u2019s soldiers carry cut branches as cover","Macbeth orders the wood burned"], ans:2 },
    { tag:"climax", q:"What news reaches Macbeth shortly before the final battle?", opts:["Banquo\u2019s ghost has returned","Duncan\u2019s sons have fled to France","The witches have been captured","Lady Macbeth is dead"], ans:3 },
    { tag:"theme", q:"Which idea does the play keep returning to through Macbeth\u2019s choices?", opts:["Unchecked ambition destroys the one who pursues it","Loyalty is always rewarded","Fate can be escaped through courage","Kings are chosen by the people"], ans:0 },
    { tag:"theme", q:"What does the recurring image of blood on the hands suggest?", opts:["Victory in battle","Royal inheritance","Guilt that cannot be washed away","Loyalty between soldiers"], ans:2 },
    { tag:"theme", q:"How does the play treat the witches\u2019 prophecies?", opts:["They are false and never come true","They tempt Macbeth, but his own choices bring his downfall","They are the only cause of his crimes","Every character ignores them"], ans:1 }
  ];
})();
</script>""".replace("MARK", MARK).replace("IDTHANE", str(id_thane)).replace("IDTYRANT", str(id_tyrant))

shutil.copyfile(SRC, SRC + ".bak")
shutil.copyfile(ASSETS, ASSETS + ".bak")
src = src.replace(ANCHOR, block + ANCHOR, 1)
assets["a%d" % id_thane] = IMG_THANE
assets["a%d" % id_tyrant] = IMG_TYRANT
open(SRC, "w", encoding="utf-8").write(src)
json.dump(assets, open(ASSETS, "w", encoding="utf-8"), separators=(",", ":"))
print("[fix_act_1_data] OK -- DATA.acts (2), DATA.actGate.macbeth (6); art in a%d, a%d" % (id_thane, id_tyrant))
